#[verus_verify]
impl Waiter {
    #[verus_spec(ret => ensures ret.0.rel_waker(ret.1))]
    pub fn new_pair() -> (Self, Arc<Waker>) {
        let waker = Arc::new(Waker {
            has_woken: AtomicBool::new(Ghost(()), false, Tracked(())),
            task: Arc::new(Task {}),
