    #[verus_spec(ret => ensures self.rel_waker(ret))]
    pub fn waker(&self) -> Arc<Waker> { self.waker.clone() }
    pub fn task(&self) -> &Arc<Task> { &self.waker.task }
    pub fn drop(self) { self.waker.close(); }
}

