    #[verifier::external_body]
    pub fn wake_up(&self) -> bool { unimplemented!() }
    #[track_caller]
    #[verifier::external_body]
    fn do_wait(&self) { unimplemented!() }
    fn close(&self) {
        proof! { use_type_invariant(self); }
        let _ = atomic_with_ghost! {
            self.has_woken => swap(true);
            update _prev -> _next;
            ghost _g => {}
